        n = len(h_best)
    except Exception:
        h_best = np.full(350, 0.5)
        n = 350
    h_best = project_feasible(h_best, n)
    best_c = compute_c5(h_best, n)

    # Phase 1: SLSQP from initial
    h1, c1 = slsqp_opt(h_best, n, [5000, 50000, 500000], 500, deadline)
    if c1 < best_c:
        h_best, best_c = h1, c1

    # Phase 2: Exact coordinate descent (many passes)
    h2, c2 = exact_cd(h_best, n, 500, deadline)
    if c2 < best_c:
        h_best, best_c = h2, c1

    # Phase 3: Multi-n exploration
    n_list = [400, 500, 600, 800, 1000, 350, 550]
    for n_try in n_list:
        if time.time() > deadline - 300:
            break
        if n_try == n:
            continue
        x_old = np.linspace(0, 2, len(h_best))
        x_new = np.linspace(0, 2, n_try)
        h_int = project_feasible(np.interp(x_new, x_old, h_best), n_try)
        h_o, c_o = slsqp_opt(h_int, n_try, [10000, 100000], 300, deadline)
        h_o, c_o = exact_cd(h_o, n_try, 200, deadline)
        if c_o < best_c - 1e-6:
            h_best, best_c = h_o, c_o
            n = n_try

    # Phase 4: Shake and settle
    n = len(h_best)
    for r in range(8):
        if time.time() > deadline - 100:
            break
        s = 0.01 + 0.03 * r
        hp = project_feasible(h_best + rng.normal(0, s, n), n)
        h_o, c_o = slsqp_opt(hp, n, [50000, 500000], 300, deadline)
        h_o, c_o = exact_cd(h_o, n, 150, deadline)
        if c_o < best_c:
            h_best, best_c = h_o, c_o

    # Phase 5: Subgradient + CD cycle
    if time.time() < deadline - 60:
        for _ in range(3):
            if time.time() > deadline - 40:
                break
            h_sg = subgrad_perturb(h_best, n, 5, deadline, scale=0.005)
            h_o, c_o = exact_cd(h_sg, n, 200, deadline)
            if c_o < best_c:
                h_best, best_c = h_o, c_o

    # Phase 6: Final polish
    if time.time() < deadline - 5:
        n = len(h_best)
        h_f, c_f = exact_cd(h_best, n, 200, deadline)
        if c_f < best_c:
            h_best, best_c = h_f, c_f

    h_best = project_feasible(h_best, len(h_best))
    best_c = compute_c5(h_best, len(h_best))
    return h_best, best_c, len(h_best)
